package glitch

import data.glitch_lib

# Container Root Privileges Detection
container_privilege_attrs := {"privileged", "runAsUser", "runAsNonRoot", "allowPrivilegeEscalation"}

check_container_privilege(attr) {
    attr.name == "privileged"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
} else {
    attr.name == "runAsUser"
    attr.value.ir_type == "Integer"
    attr.value.value == 0
} else {
    attr.name == "runAsUser"
    attr.value.ir_type == "String"
    attr.value.value == "root"
} else {
    attr.name == "runAsNonRoot"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "allowPrivilegeEscalation"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Overly Permissive IAM Detection
iam_attrs := {"Action", "Resource"}

check_wildcard(value) {
    value.ir_type == "String"
    contains(value.value, "*")
} else {
    value.ir_type == "Array"
    some element in value.value
    element.ir_type == "String"
    contains(element.value, "*")
}

# Compute Instance Root User Detection
compute_user_attrs := {"admin_username", "user", "username"}

check_root_user(value) {
    value.ir_type == "String"
    value.value == "root"
} else {
    value.ir_type == "String"
    value.value == "admin"
}

check_user_data(value) {
    value.ir_type == "String"
    regex.match("(?i)sudo.*nopasswd", value.value)
}

# Service Account Token Mounting Detection
check_automount(value) {
    value.ir_type == "Boolean"
    value.value == true
}

# File System Permissions Detection
mode_set := {"mode", "m"}

check_permission(value) {
    value.ir_type == "String"
    regex.match("(?:^0?777$)|(?:(?:^|(?:ugo)|o|a)\\+[rwx]{3})", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 777
}

# Secrets Detection
secret_attrs := {"secret_string", "secret", "password", "token"}

# Main Glitch_Analysis rule
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Container Root Privileges
    attr.name in container_privilege_attrs
    check_container_privilege(attr)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Container running with root privileges - Containers should not run as root or with privileged mode. (CWE-250)"
    }
}

Glitch_Analysis[result] {
