    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Overly Permissive IAM
    attr.name in iam_attrs
    check_wildcard(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive IAM policy - Policies should not use wildcards or high-privilege actions unnecessarily. (CWE-250)"
