package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type == "container"
    attrs := glitch_lib.all_attributes(node)

    privileged_attr := {a | a := attrs[_]; a.name == "privileged"; a.value.ir_type == "Boolean"; a.value.value == true}
    run_as_user_attr := {a | a := attrs[_]; a.name == "runAsUser"; a.value.ir_type == "String"; a.value.value == "0"}
    run_as_root_attr := {a | a := attrs[_]; a.name == "runAsUser"; a.value.ir_type == "String"; a.value.value == "root"}
    run_as_non_root_attr := {a | a := attrs[_]; a.name == "runAsNonRoot"; a.value.ir_type == "Boolean"; a.value.value == false}
    allow_priv_esc_attr := {a | a := attrs[_]; a.name == "allowPrivilegeEscalation"; a.value.ir_type == "Boolean"; a.value.value == true}

    count(privileged_attr) > 0
    or count(run_as_user_attr) > 0
    or count(run_as_root_attr) > 0
    or count(run_as_non_root_attr) > 0
    or count(allow_priv_esc_attr) > 0

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Container runs with excessive privileges (CWE-250)."
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type == "iam_policy"
    attrs := glitch_lib.all_attributes(node)

    action_attr := {a | a := attrs[_]; a.name == "Action"; a.value.ir_type == "String"; regex.match(".*\\*.*", a.value.value)}
    resource_attr := {a | a := attrs[_]; a.name == "Resource"; a.value.ir_type == "String"; a.value.value == "*"}

    count(action_attr) > 0 or count(resource_attr) > 0

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "IAM policy uses wildcard permissions (CWE-250)."
    }
}

